api.localhost {
    tls internal # Use Caddy's internal CA for local certs

    # Block admin panel on API domain (use admin subdomain instead)
    handle /admin/* {
        respond 404
    }

    reverse_proxy nginx:80 {
        header_up Host {host} # Preserve original Host header
        header_up X-Forwarded-Proto https
    }
}

# Admin Panel
admin.localhost {
    tls internal
    reverse_proxy nginx:80 {
        header_up Host {host}
        header_up X-Forwarded-Proto https
    }
}


# QGIS Server
qgis.localhost {
    tls internal

    # Forward authentication to Django
    route {
        # Authenticate all requests via Django
        forward_auth nginx:80 {
            uri /api/v1/auth/qgis-auth/
            copy_headers Authorization
        }

        # Proxy to QGIS Server
        reverse_proxy qgis-server:80 {
            header_up Host {host}
            header_up X-Forwarded-Proto https
        }
    }
}

# Frontend
app.localhost {
    tls internal # Use Caddy's internal CA for local certs
    reverse_proxy frontend:3000 {
        header_up Host {host} # Preserve original Host header
        header_up X-Forwarded-Proto {scheme}
    }
}

# WebDAV File Access
files.localhost {
    tls internal # Use Caddy's internal CA for local certs

    # Forward authentication to Django
    route {
        # Authenticate all requests via Django
        forward_auth nginx:80 {
            uri /api/v1/auth/webdav-auth/
            copy_headers Authorization
        }

        # Serve files via WebDAV
        webdav {
            root /media
            prefix /
        }
    }
}

# Vector Tile Server
tiles.localhost {
    tls internal # Use Caddy's internal CA for local certs
    reverse_proxy tileserver:8080 {
        header_up Host {host}
        header_up X-Forwarded-Proto https
    }
    # Allow CORS for tile requests
    header {
        Access-Control-Allow-Origin *
        Access-Control-Allow-Methods "GET, OPTIONS"
    }
